// Intended function: promote observations into usable knowledge only when prerequisite/confidence gates are met, retaining source provenance for Chronicle/UI inspection.
#include "research/KnowledgeSystem.hpp"
#include <algorithm>
namespace elysium{bool KnowledgeSystem::add(KnowledgeRecord r){if(!r.knowledgeId||records_.contains(r.knowledgeId))return false;records_[r.knowledgeId]=std::move(r);return true;}bool KnowledgeSystem::improveConfidence(std::uint64_t id,float d,std::uint64_t src){auto i=records_.find(id);if(i==records_.end())return false;i->second.confidence=std::clamp(i->second.confidence+d,0.f,1.f);if(src)i->second.sourceStableId=src;return true;}std::optional<KnowledgeRecord>KnowledgeSystem::find(std::uint64_t id)const{auto i=records_.find(id);return i==records_.end()?std::nullopt:std::optional<KnowledgeRecord>(i->second);}std::vector<KnowledgeRecord>KnowledgeSystem::availableTechniques()const{std::vector<KnowledgeRecord>o;for(auto&[_,r]:records_){if(r.kind!=KnowledgeKind::Technique||r.confidence<.75f)continue;bool ok=true;for(auto p:r.prerequisites){auto i=records_.find(p);if(i==records_.end()||i->second.confidence<.65f){ok=false;break;}}if(ok)o.push_back(r);}std::sort(o.begin(),o.end(),[](auto&a,auto&b){return a.knowledgeId<b.knowledgeId;});return o;}}
